'use client'

import * as React from 'react'
import { Check, EditPencil, NavArrowDown } from 'iconoir-react'
import { cn } from '@/lib/utils'
import { FlappySprite, TetrisStill, type AgentLoadingIndicator } from '@/registry/satin/ui/agent-loading'
import { useSatinLabels } from '@/registry/satin/ui/labels'

/**
 * Thinking, 1:1 with the uiKit `Thinking` set (3239:20908) and its parts thinking/header
 * (3239:20766), thinking/step (3239:20791) and thinking/_mark (3239:20674).
 *
 * What an agent did, once it is done; while it works, AgentLoading (agent-loading.tsx) shows
 * instead. collapsed: the mark at rest (the full tetris board, or the flappy bird), summary
 * and a 14px chevron. expanded: the same header with the chevron turned up, then 8px down a body
 * with 4px left inset: a 16px rail (1px line, rail-edge → rail-center → rail-edge) and, 12px
 * on, the steps 8px apart.
 *
 * The header is a button (click, Enter, Space) that opens and folds the body with the
 * Accordion's motion; the folded body stays mounted but leaves tab order and screen readers.
 * `state` sets the starting state and follows later changes, `onToggle` reports them.
 */
export type ThinkingStep =
  /** A finished action: green check, label, muted meta that truncates. */
  | { type?: 'task'; label: React.ReactNode; meta?: React.ReactNode }
  /** A thought, wrapping in text/muted. */
  | { type: 'text'; text: React.ReactNode }
  /** A page that was read: 16px favicon, title, muted meta. */
  | { type: 'source'; icon?: React.ReactNode; label: React.ReactNode; meta?: React.ReactNode }
  /** A dev tool call: icon (pencil by default), name, mono target, +added −removed, meta. */
  | {
      type: 'tool'
      icon?: React.ReactNode
      label: React.ReactNode
      target?: React.ReactNode
      added?: React.ReactNode
      removed?: React.ReactNode
      meta?: React.ReactNode
    }
  /** The rest, folded: "+5 more". */
  | { type: 'more'; label: React.ReactNode }

export type ThinkingState = 'collapsed' | 'expanded'
/** The mark beside the summary, matching the AgentLoading that ran before it. */
export type ThinkingIndicator = AgentLoadingIndicator

export interface ThinkingProps extends Omit<React.ComponentProps<'div'>, 'onToggle'> {
  /** collapsed once the agent is done, expanded when people open it. */
  state?: ThinkingState
  /** The summary, e.g. "Thought for 2m 45s". Defaults to the `thought` label ("Thought"). */
  label?: React.ReactNode
  steps?: ThinkingStep[]
  /** The mark beside the summary. */
  indicator?: ThinkingIndicator
  onToggle?: (open: boolean) => void
}

export function Thinking({
  state = 'collapsed',
  label: labelProp,
  steps = [],
  indicator = 'tetris',
  onToggle,
  className,
  ...props
}: ThinkingProps) {
  const labels = useSatinLabels()
  const label = labelProp ?? labels.thought
  const [open, setOpen] = React.useState(state === 'expanded')
  React.useEffect(() => setOpen(state === 'expanded'), [state])
  const bodyId = `${React.useId()}-steps`

  return (
    <div data-slot="thinking" data-state={open ? 'expanded' : 'collapsed'} className={cn('sa:w-full', className)} {...props}>
      <button
        type="button"
        aria-expanded={open}
        aria-controls={bodyId}
        onClick={() => {
          setOpen(!open)
          onToggle?.(!open)
        }}
        className="sa:group sa:flex sa:w-fit sa:cursor-pointer sa:items-center sa:gap-3 sa:rounded-md sa:p-1 sa:outline-none sa:select-none sa:focus-visible:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]"
      >
        <ThinkingMark indicator={indicator} />
        <span className="sa:text-sm sa:whitespace-nowrap sa:text-text-muted">{label}</span>
        <NavArrowDown
          aria-hidden
          className={cn(
            'sa:size-icon-size-sm sa:shrink-0 sa:text-text-muted sa:transition-transform sa:duration-(--sa-duration-base) sa:ease-(--sa-ease-out) sa:[stroke-width:1.875]',
            open && 'sa:rotate-180',
          )}
        />
      </button>
      {/* The Accordion's motion (satin-expand): the body grows down from under the header, which
          never moves, and its steps settle in from the top edge; closing is quicker. */}
      <div id={bodyId} data-state={open ? 'open' : 'closed'} className="satin-expand">
        <div>
          <div className="sa:flex sa:gap-3 sa:ps-1 sa:pt-2">
            <div aria-hidden className="sa:relative sa:w-4 sa:shrink-0 sa:self-stretch">
              <div className="sa:absolute sa:inset-y-0 sa:left-1/2 sa:w-px sa:-translate-x-1/2 sa:bg-linear-to-b sa:from-component-rail-edge sa:via-component-rail-center sa:to-component-rail-edge" />
            </div>
            <ol className="sa:flex sa:min-w-0 sa:flex-1 sa:flex-col sa:gap-2">
              {steps.map((step, i) => (
                <li key={i} className="sa:min-w-0">
                  <Step step={step} />
                </li>
              ))}
            </ol>
          </div>
        </div>
      </div>
    </div>
  )
}

function Step({ step }: { step: ThinkingStep }) {
  switch (step.type) {
    case 'text':
      return <p className="sa:text-body sa:text-text-muted">{step.text}</p>
    case 'more':
      return <p className="sa:text-sm sa:whitespace-nowrap sa:text-text-muted">{step.label}</p>
    case 'source':
      return (
        <div className="sa:flex sa:min-w-0 sa:items-center sa:gap-3 sa:p-1 sa:text-sm">
          <span className="sa:flex sa:size-4 sa:shrink-0 sa:items-center sa:justify-center sa:overflow-clip sa:rounded-xs sa:[&>*]:size-4">
            {step.icon}
          </span>
          <span className="sa:max-w-full sa:shrink-0 sa:truncate sa:text-text-default">{step.label}</span>
          {step.meta != null && <span className="sa:min-w-0 sa:flex-1 sa:truncate sa:text-text-muted">{step.meta}</span>}
        </div>
      )
    case 'tool':
      return (
        <div className="sa:flex sa:min-w-0 sa:items-center sa:gap-2 sa:p-1 sa:text-sm sa:[&>svg]:size-icon-size sa:[&>svg]:shrink-0 sa:[&>svg]:text-text-muted sa:[&>svg]:[stroke-width:1.875]">
          {step.icon ?? <EditPencil />}
          <span className="sa:shrink-0 sa:whitespace-nowrap sa:text-text-default">{step.label}</span>
          <span className="sa:min-w-0 sa:flex-1 sa:truncate sa:font-mono sa:tracking-normal sa:text-text-muted">{step.target}</span>
          {(step.added != null || step.removed != null) && (
            <span className="sa:flex sa:shrink-0 sa:gap-1.5 sa:font-mono sa:tracking-normal sa:whitespace-nowrap">
              {step.added != null && <span className="sa:text-status-green-fg">{step.added}</span>}
              {step.removed != null && <span className="sa:text-status-red-fg">{step.removed}</span>}
            </span>
          )}
          {step.meta != null && <span className="sa:shrink-0 sa:whitespace-nowrap sa:text-text-muted">{step.meta}</span>}
        </div>
      )
    default:
      return (
        <div className="sa:flex sa:min-w-0 sa:items-center sa:gap-3 sa:p-1 sa:text-sm">
          <Check aria-hidden className="sa:size-icon-size-sm sa:shrink-0 sa:text-status-green-fg sa:[stroke-width:1.875]" />
          <span className="sa:max-w-full sa:shrink-0 sa:truncate sa:text-text-default">{step.label}</span>
          {step.meta != null && <span className="sa:min-w-0 sa:flex-1 sa:truncate sa:text-text-muted">{step.meta}</span>}
        </div>
      )
  }
}

/** thinking/_mark: the tetris board filled, or the flappy bird at rest. */
function ThinkingMark({ indicator }: { indicator: ThinkingIndicator }) {
  return indicator === 'flappy' ? <FlappySprite size={16} run={false} /> : <TetrisStill />
}
